CREATE TABLE "workers" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "keycloak_id" VARCHAR(255) UNIQUE NOT NULL,
    "first_name" VARCHAR NOT NULL,
    "last_name" VARCHAR NOT NULL,
    "email" VARCHAR UNIQUE NOT NULL
);

CREATE TYPE status AS ENUM ('PLANNED', 'IN_PROGRESS', 'CLOSED');
CREATE TABLE "orders" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "description" TEXT,
    "created_at" TIMESTAMP WITH TIME ZONE NOT NULL,
    "status" status NOT NULL
);

CREATE TABLE "work_steps" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(50) NOT NULL,
    "description" TEXT,
    "start_date" TIMESTAMP WITH TIME ZONE,
    "end_date" TIMESTAMP WITH TIME ZONE,
    "status" status NOT NULL,
    "order_id" BIGINT NOT NULL,

    CONSTRAINT fk_work_step_order
        FOREIGN KEY (order_id)
        REFERENCES orders(id)
);

CREATE TABLE "price_tags" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(50) NOT NULL,
    "unit_price" NUMERIC(10, 2) NOT NULL,
    "is_active" BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE "work_tasks" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(50) NOT NULL,
    "description" TEXT,
    "start_date" TIMESTAMP WITH TIME ZONE,
    "end_date" TIMESTAMP WITH TIME ZONE,
    "status" status NOT NULL,
    "unit_quantity" NUMERIC(10, 2) NOT NULL,
    "price_snapshot" NUMERIC(10, 2) NOT NULL,
    "work_step_id" BIGINT NOT NULL,
    "price_tag_id" BIGINT NOT NULL,

    CONSTRAINT fk_work_task_work_step
        FOREIGN KEY (work_step_id)
        REFERENCES work_steps(id),

    CONSTRAINT fk_work_task_price_tag
        FOREIGN KEY (price_tag_id)
        REFERENCES price_tags(id)
);

CREATE TABLE "work_reports" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "created_at" TIMESTAMP WITH TIME ZONE NOT NULL,
    "comment" TEXT NOT NULL,
    "is_accepted" BOOLEAN NOT NULL,
    "work_task_id" BIGINT,
    "work_step_id" BIGINT,

    CONSTRAINT chk_report_target
        CHECK (
            (work_step_id IS NOT NULL AND work_task_id IS NULL)
            OR
            (work_step_id IS NULL AND work_task_id IS NOT NULL)
        ),

    CONSTRAINT fk_report_work_step
        FOREIGN KEY (work_step_id)
        REFERENCES work_steps(id),

    CONSTRAINT fk_report_work_task
        FOREIGN KEY (work_task_id)
        REFERENCES work_tasks(id)
);

CREATE TABLE "work_report_photos" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "work_report_id" BIGINT NOT NULL,
    "storage_key" TEXT NOT NULL,
    "original_filename" TEXT,
    "content_type" VARCHAR(100),
    "created_at" TIMESTAMP WITH TIME ZONE NOT NULL,

    CONSTRAINT fk_photo_report
        FOREIGN KEY (work_report_id)
        REFERENCES work_reports(id)
        ON DELETE CASCADE
);

CREATE TABLE "workers_assigned" (
    "worker_id" BIGINT NOT NULL,
    "work_task_id" BIGINT NOT NULL,

    PRIMARY KEY (worker_id, work_task_id),

    CONSTRAINT fk_assigned_worker
        FOREIGN KEY (worker_id)
        REFERENCES workers(id),

    CONSTRAINT fk_assigned_work_task
        FOREIGN KEY (work_task_id)
        REFERENCES work_tasks(id)
);



